BEGIN TRANSACTION;
CREATE TABLE `entries` (`id` INTEGER NOT NULL, `mdc` TEXT NOT NULL, `glyph` TEXT NOT NULL, `translit` TEXT NOT NULL, `translitRaw` TEXT NOT NULL, `translation` TEXT NOT NULL, `meaning` TEXT NOT NULL, `pos` TEXT NOT NULL, `gardinerCodesCsv` TEXT NOT NULL, `isFavorite` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE `gardiner_categories` (`code` TEXT NOT NULL, `title` TEXT NOT NULL, `description` TEXT NOT NULL, `count` INTEGER NOT NULL, `sortOrder` INTEGER NOT NULL, PRIMARY KEY(`code`));
CREATE TABLE `gardiner_signs` (`code` TEXT NOT NULL, `categoryCode` TEXT NOT NULL, `glyph` TEXT NOT NULL, `name` TEXT NOT NULL, `meaning` TEXT NOT NULL, `num` INTEGER NOT NULL, PRIMARY KEY(`code`), FOREIGN KEY(`categoryCode`) REFERENCES `gardiner_categories`(`code`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE TABLE room_master_table (id INTEGER PRIMARY KEY, identity_hash TEXT);
CREATE TABLE `word_sign_cross_ref` (`wordId` INTEGER NOT NULL, `signCode` TEXT NOT NULL, PRIMARY KEY(`wordId`, `signCode`));
CREATE INDEX `index_entries_isFavorite` ON `entries` (`isFavorite`);
CREATE INDEX `index_entries_translitRaw` ON `entries` (`translitRaw`);
CREATE INDEX `index_entries_glyph` ON `entries` (`glyph`);
CREATE INDEX `index_gardiner_signs_categoryCode` ON `gardiner_signs` (`categoryCode`);
CREATE INDEX `index_word_sign_cross_ref_wordId` ON `word_sign_cross_ref` (`wordId`);
CREATE INDEX `index_word_sign_cross_ref_signCode` ON `word_sign_cross_ref` (`signCode`);
COMMIT;
